// TOU/ULO holiday pricing days, generated by rule and checked against the OEB's published schedule.
// Source: OEB, "Holiday schedule - Time-of-Use and Ultra-Low Overnight"
//   https://www.oeb.ca/consumer-information-and-protection/electricity-rates/holiday-schedule-time-use-and-ultra-low
//   Rule quoted there: if a holiday falls on a weekend, the next weekday that is not also a holiday has holiday prices all day.
import { weekdayOf, addDays } from './time.js';

const pad = n => String(n).padStart(2, '0');
const ymd = (y, m, d) => `${y}-${pad(m)}-${pad(d)}`;
function nthWeekday(y, m, wd, n) { // wd 1=Mon..7=Sun
  const first = weekdayOf(ymd(y, m, 1));
  return ymd(y, m, 1 + ((wd - first + 7) % 7) + 7 * (n - 1));
}
function easter(y) { // Anonymous Gregorian algorithm
  const a = y % 19, b = Math.floor(y / 100), c = y % 100, d = Math.floor(b / 4), e = b % 4, f = Math.floor((b + 8) / 25), g = Math.floor((b - f + 1) / 3);
  const h = (19 * a + b - d - g + 15) % 30, i = Math.floor(c / 4), k = c % 4, l = (32 + 2 * e + 2 * i - h - k) % 7, m = Math.floor((a + 11 * h + 22 * l) / 451);
  const month = Math.floor((h + l - 7 * m + 114) / 31), day = ((h + l - 7 * m + 114) % 31) + 1;
  return ymd(y, month, day);
}
function victoriaDay(y) { // Monday preceding May 25
  let d = ymd(y, 5, 24);
  while (weekdayOf(d) !== 1) d = addDays(d, -1);
  return d;
}

/** The ten holidays the OEB lists, before weekend shifting. */
export function nominalHolidays(y) {
  return [
    [ymd(y, 1, 1), "New Year's Day"], [nthWeekday(y, 2, 1, 3), 'Family Day'], [addDays(easter(y), -2), 'Good Friday'],
    [victoriaDay(y), 'Victoria Day'], [ymd(y, 7, 1), 'Canada Day'], [nthWeekday(y, 8, 1, 1), 'Civic Holiday'],
    [nthWeekday(y, 9, 1, 1), 'Labour Day'], [nthWeekday(y, 10, 1, 2), 'Thanksgiving Day'], [ymd(y, 12, 25), 'Christmas Day'], [ymd(y, 12, 26), 'Boxing Day'],
  ];
}

/** Days on which holiday pricing applies in year y: Map(date -> holiday name). */
export function holidayPricingDays(y) {
  const out = new Map();
  for (const [d, name] of nominalHolidays(y)) {
    let day = d;
    while (weekdayOf(day) >= 6 || out.has(day)) day = addDays(day, 1);
    out.set(day, name);
  }
  return out;
}

const cache = new Map();
export function isHoliday(dateStr) {
  const y = +dateStr.slice(0, 4);
  // Boxing Day shifting can spill into the next year's early January only in theory; check both years.
  for (const yy of [y, y - 1]) {
    if (!cache.has(yy)) cache.set(yy, holidayPricingDays(yy));
    if (cache.get(yy).has(dateStr)) return true;
  }
  return false;
}
